CATALOG = {}
for _row in _ROWS.strip().splitlines():
    if not _row.strip():
        continue
    _source, *_translations = (part.replace("\\n", "\n") for part in _row.split("|"))
    if len(_translations) != len(_LANGUAGES):
        raise ValueError(f"Invalid client translation row: {_source}")
    CATALOG[_source] = dict(zip(_LANGUAGES, _translations))

# The product name is a brand and remains the same in each interface language.
CATALOG["Lineage 2 Chat Translator"] = {code: "Lineage 2 Chat Translator" for code in _LANGUAGES}
